    "title": "Colossal Biosciences Pursues New Funding With Sky-High Valuation Expectations",
    "category": "business",
    "categoryLabel": "Business",
    "icon": "💰",
    "date": "2026-07-21",
    "readTime": "6 min",
    "topic": "biotechnology",
